'use strict';

function tell(seed) {
  const table = [20, 40, 60, 80, 100];
  let acc = 67;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 59 + c * table[i % table.length]) % 9199;
    out += String.fromCharCode(97 + ((c * 6 + acc) % 26));
  }
  return `direct-eval-lexical:tell:${acc}:${out}`;
}
exports.tell = tell;

function passenger(seed) {
  const table = [21, 35, 49, 63, 77];
  let acc = 73;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc + (c * 17 ^ table[i % table.length])) % 8887;
    out += String.fromCharCode(65 + ((c * 7 + acc) % 26));
  }
  return `direct-eval-lexical:passenger:${acc}:${out}`;
}
exports.passenger = passenger;
